UPDATE REP_CASH_YIELD as A, ( select BUSI_ID, CASH_ID, CASH_NAME, CASH_TYPE, CASH_TYPE2, START_DATE, REMARK, INPUT_TYPE, INPUT_USER, STATUS, ADAPTER_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, RATE, CHARGE_RATIO from ( select TEMP.* from (
SELECT #{item.busiId,jdbcType=VARCHAR} as BUSI_ID, F_GUID() as CASH_ID, #{item.cashName,jdbcType=VARCHAR} as CASH_NAME, #{item.cashType,jdbcType=VARCHAR} as CASH_TYPE, #{item.cashType2,jdbcType=VARCHAR} as CASH_TYPE2, #{item.startDate,jdbcType=DATE} as START_DATE, #{item.remark,jdbcType=VARCHAR} as REMARK, #{item.inputType,jdbcType=VARCHAR} as INPUT_TYPE, #{item.inputUser,jdbcType=VARCHAR} as INPUT_USER, #{item.status,jdbcType=VARCHAR} as STATUS, 'interf' as ADAPTER_ID, #{item.createUser,jdbcType=VARCHAR} as CREATE_USER, #{item.createDept,jdbcType=VARCHAR} as CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} as CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} as UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} as UPDATE_TIME, #{item.rate,jdbcType=DECIMAL} as RATE, #{item.chargeRatio,jdbcType=DECIMAL} as CHARGE_RATIO from dual
) TEMP ) de ) AS B SET A.CASH_ID = B.CASH_ID , A.CASH_NAME = B.CASH_NAME , A.CASH_TYPE = B.CASH_TYPE , A.REMARK = B.REMARK , A.INPUT_TYPE = B.INPUT_TYPE , A.INPUT_USER = B.INPUT_USER , A.STATUS = B.STATUS , A.ADAPTER_ID = B.ADAPTER_ID , A.CREATE_USER= B.CREATE_USER , A.CREATE_DEPT= B.CREATE_DEPT , A.CREATE_TIME= B.CREATE_TIME , A.UPDATE_USER= B.UPDATE_USER , A.UPDATE_TIME= B.UPDATE_TIME , A.RATE = B.RATE, A.CHARGE_RATIO= B.CHARGE_RATIO where A.BUSI_ID = B.BUSI_ID and A.CASH_TYPE2 = B.CASH_TYPE2 and A.START_DATE = B.START_DATE; insert into REP_CASH_YIELD(BUSI_ID, CASH_ID, CASH_NAME, CASH_TYPE, CASH_TYPE2, START_DATE, REMARK, INPUT_TYPE, INPUT_USER, STATUS, ADAPTER_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, RATE, CHARGE_RATIO) select BUSI_ID, CASH_ID, CASH_NAME, CASH_TYPE, CASH_TYPE2, START_DATE, REMARK, INPUT_TYPE, INPUT_USER, STATUS, ADAPTER_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, RATE, CHARGE_RATIO from ( select TEMP.* from (
SELECT #{item.busiId,jdbcType=VARCHAR} as BUSI_ID, F_GUID() as CASH_ID, #{item.cashName,jdbcType=VARCHAR} as CASH_NAME, #{item.cashType,jdbcType=VARCHAR} as CASH_TYPE, #{item.cashType2,jdbcType=VARCHAR} as CASH_TYPE2, #{item.startDate,jdbcType=DATE} as START_DATE, #{item.remark,jdbcType=VARCHAR} as REMARK, #{item.inputType,jdbcType=VARCHAR} as INPUT_TYPE, #{item.inputUser,jdbcType=VARCHAR} as INPUT_USER, #{item.status,jdbcType=VARCHAR} as STATUS, 'interf' as ADAPTER_ID, #{item.createUser,jdbcType=VARCHAR} as CREATE_USER, #{item.createDept,jdbcType=VARCHAR} as CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} as CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} as UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} as UPDATE_TIME, #{item.rate,jdbcType=DECIMAL} as RATE, #{item.chargeRatio,jdbcType=DECIMAL} as CHARGE_RATIO from dual
) TEMP where not exists (select 1 from REP_CASH_YIELD CII where CII.BUSI_ID=TEMP.BUSI_ID and CII.CASH_TYPE2 = TEMP.CASH_TYPE2 and CII.START_DATE = TEMP.START_DATE) ) de ;
